  /// Clean input word: lowercase, strip punctuation marks, but keep valid contractions
  static String cleanWord(String raw) {
    var s = raw.toLowerCase().trim();
    // Handle possessive 's at the end (e.g. Earth's -> earth, doctor's -> doctor)
    if (s.endsWith("'s")) {
      s = s.substring(0, s.length - 2);
    } else if (s.endsWith("'") && s.length > 2) {
      s = s.substring(0, s.length - 1);
    }
    // Strip any remaining surrounding non-alphanumeric punctuation except inner apostrophe/hyphen
    s = s.replaceAll(RegExp(r"^[^a-zA-Z0-9]+"), '');
    s = s.replaceAll(RegExp(r"[^a-zA-Z0-9]+$"), '');
    return s;
  }

  /// Look up word definition synchronously with comprehensive rules and stemming
  static WordDefinition lookup(String raw) {
    final clean = cleanWord(raw);
    if (clean.isEmpty) {
      return WordDefinition(
        word: raw,
        turkishMeaning: 'Kelime bulunamadı',
        partOfSpeech: '-',
      );
    }

    // 1. Direct contraction match
    if (_contractions.containsKey(clean)) {
      return WordDefinition(
        word: clean,
        turkishMeaning: _contractions[clean]!,
        partOfSpeech: 'kısaltma',
      );
    }

    // 3. Irregular verbs
    if (_irregularVerbs.containsKey(clean)) {
      final base = _irregularVerbs[clean]!;
      if (_dictionary.containsKey(base)) {
        final baseDef = _dictionary[base]!;
        return WordDefinition(
          word: clean,
          turkishMeaning: '${baseDef.turkishMeaning} (fiil hali)',
          partOfSpeech: 'fiil',
          phonetic: baseDef.phonetic,
        );
      }
    }

    // 4. Irregular plurals
    if (_irregularPlurals.containsKey(clean)) {
      final base = _irregularPlurals[clean]!;
      if (_dictionary.containsKey(base)) {
        final baseDef = _dictionary[base]!;
        return WordDefinition(
          word: clean,
          turkishMeaning: '${baseDef.turkishMeaning} (çoğul)',
          partOfSpeech: 'isim (çoğul)',
          phonetic: baseDef.phonetic,
        );
      }
    }

    // 5. Morphological stemming rules (prefer base lemma if available):
    // a) plural -ies -> -y
    if (clean.endsWith('ies') && clean.length > 4) {
      final base = '${clean.substring(0, clean.length - 3)}y';
      if (_dictionary.containsKey(base)) return _dictionary[base]!;
    }
    // b) plural -es
    if (clean.endsWith('es') && clean.length > 3) {
      final base = clean.substring(0, clean.length - 2);
      if (_dictionary.containsKey(base)) return _dictionary[base]!;
    }
    // c) plural / 3rd person -s
    if (clean.endsWith('s') && clean.length > 2) {
      final base = clean.substring(0, clean.length - 1);
      if (_dictionary.containsKey(base)) return _dictionary[base]!;
    }
    // d) past tense -ied -> -y
    if (clean.endsWith('ied') && clean.length > 4) {
      final base = '${clean.substring(0, clean.length - 3)}y';
      if (_dictionary.containsKey(base)) return _dictionary[base]!;
    }
    // e) past tense -ed
    if (clean.endsWith('ed') && clean.length > 3) {
      final base2 = '${clean.substring(0, clean.length - 2)}e';
      if (_dictionary.containsKey(base2)) return _dictionary[base2]!;
      final base1 = clean.substring(0, clean.length - 2);
      if (_dictionary.containsKey(base1)) return _dictionary[base1]!;
    }
    // f) gerund -ing
    if (clean.endsWith('ing') && clean.length > 4) {
      final base2 = '${clean.substring(0, clean.length - 3)}e';
      if (_dictionary.containsKey(base2)) return _dictionary[base2]!;
      final base1 = clean.substring(0, clean.length - 3);
      if (_dictionary.containsKey(base1)) return _dictionary[base1]!;
    }
    // g) adverb -ly
    if (clean.endsWith('ly') && clean.length > 3) {
      final base = clean.substring(0, clean.length - 2);
      if (_dictionary.containsKey(base)) return _dictionary[base]!;
    }

    // 2. Exact match in full 5,000+ dictionary
    if (_dictionary.containsKey(clean)) {
      return _dictionary[clean]!;
    }

    // Fallback: If not found immediately, trigger async fetch in background and return pending
    lookupAsync(clean);
    return WordDefinition(
      word: clean,
      turkishMeaning: 'Anlam yükleniyor...',
      partOfSpeech: 'kelime',
    );
  }

  /// Asynchronously lookup or fetch Turkish translation online and cache it
  static Future<WordDefinition> lookupAsync(String raw) async {
    final clean = cleanWord(raw);
    if (clean.isEmpty) {
      return WordDefinition(word: raw, turkishMeaning: 'Kelime bulunamadı', partOfSpeech: '-');
    }
    if (_dictionary.containsKey(clean) && _dictionary[clean]!.turkishMeaning != 'Anlam yükleniyor...') {
      return _dictionary[clean]!;
    }

    // 1. Try Google Translate single token API (CORS enabled)
    try {
      final uri = Uri.parse('https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=tr&dt=t&q=${Uri.encodeComponent(clean)}');
      final response = await http.get(uri).timeout(const Duration(seconds: 4));
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        if (data is List && data.isNotEmpty && data[0] is List) {
          final translated = (data[0][0][0] as String).trim();
          if (translated.isNotEmpty) {
            final def = WordDefinition(
              word: clean,
              turkishMeaning: translated,
              partOfSpeech: 'kelime',
            );
            _dictionary[clean] = def;
            return def;
          }
        }
      }
    } catch (_) {}

    // 2. Try MyMemory Translation API fallback
    try {
      final uri = Uri.parse('https://api.mymemory.translated.net/get?q=${Uri.encodeComponent(clean)}&langpair=en|tr');
      final response = await http.get(uri).timeout(const Duration(seconds: 4));
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        final translated = (data['responseData']?['translatedText'] as String?)?.trim();
        if (translated != null && translated.isNotEmpty && !translated.toLowerCase().contains('mymemory')) {
          final def = WordDefinition(
            word: clean,
            turkishMeaning: translated,
            partOfSpeech: 'kelime',
          );
          _dictionary[clean] = def;
          return def;
        }
      }
    } catch (_) {}

    // Fallback if network fails
    final def = WordDefinition(
      word: clean,
      turkishMeaning: clean,
      partOfSpeech: 'kelime',
    );
    _dictionary[clean] = def;
    return def;
  }
